def get_employee(worker):
    if worker.wuser in cache['employee']:
        return cache['employee'][worker.wuser]

    employee = frappe.db.get_value('Employee', 
                    {'user_id': worker.wuser, 'status': 'Active'}, 
                    ['name', 'company', 'payroll_cost_center', 'department'], 
                    as_dict=True)

    cache['employee'][worker.wuser] = employee
    return employee

def get_employee_cost_center(worker):
    employee = get_employee(worker)

    if employee.name in cache['employee_cost_center']:
        return cache['employee_cost_center'][employee.name]

    cost_center_employee = employee.get('payroll_cost_center')

    if not cost_center_employee and employee.department:
        cost_center_employee = frappe.db.get_value('Department', employee.department, 'payroll_cost_center')

    cache['employee_cost_center'][employee.name] = cost_center_employee
    return cost_center_employee

def get_data_for_party(worker, project_company):
    if worker.wtype == "Employee":
        employee = get_employee(worker)
        if employee and employee.company:
            company_account = frappe.db.get_value('Company', 
                                                employee.company, 
                                                'default_payroll_payable_account')
            if company_account:
                return {
                    'account': company_account,
                    'party_type': 'Employee',
                    'party': employee.name
                }
    elif worker.wtype == "Supplier":
        supplier = frappe.db.sql("""
            SELECT parent FROM `tabPortal User` 
            WHERE parenttype = 'Supplier' AND user = %s
            LIMIT 1
        """, worker.wuser, as_dict=True)

        if supplier:
            supplier_name = supplier[0].parent
            supplier_doc = frappe.get_cached_doc('Supplier', supplier_name)

            # 1. Ищем account в Supplier для компании проекта
            account = None
            for acc in supplier_doc.accounts:
                if acc.company == project_company:
                    account = acc.account
                    break

            # 2. Если не нашли в Supplier, ищем в Supplier Group
            if not account and supplier_doc.supplier_group:
                supplier_group = frappe.get_cached_doc('Supplier Group', supplier_doc.supplier_group)
                for acc in supplier_group.accounts:
                    if acc.company == project_company:
                        account = acc.account
                        break

            # 3. Если account не найден ни в Supplier, ни в Supplier Group - ошибка
            if not account:
                frappe.throw(f"Не найден account для компании {project_company} у поставщика {supplier_name} и его группы {supplier_doc.supplier_group}")

            return {
                'account': account,
                'party_type': 'Supplier',
                'party': supplier_name
            }
    return None

def get_round_off_account(company):
    """Получает счет округления из настроек компании"""
    company_doc = frappe.get_cached_doc('Company', company)
    if not company_doc.round_off_account:
        frappe.throw(f"В компании {company} не настроен счет округления (round_off_account)")
    return company_doc.round_off_account


log("_________________ Create Journal Entries for Approved Timesheet _________________")

user_timesheet = frappe.get("form_dict", args).get("doc")
log("Doc: " + frappe.utils.cstr(user_timesheet))

worker_name = frappe.db.get_value('Worker',
    {'wuser': user_timesheet.timesheet_from},
    ['name'],
    as_dict=1
)
worker = frappe.get_cached_doc('Worker', worker_name.name)

if not worker:
    log("Ошибка: Worker не найден")
    frappe.throw(f"Worker не найден для пользователя {user_timesheet.timesheet_from}")

K = user_timesheet.normalization if user_timesheet.normalization is not None else 1

user_timesheet_positions = frappe.db.get_all(
    'User Timesheet Position',
    filters={'user_timesheet': user_timesheet.name},
    fields=['name', 'project', 'document_name', 'user', 'project_role'],
    ignore_permissions=True
)

log(f"Найдено {len(user_timesheet_positions)} позиций в User Timesheet")

for idx, utp in enumerate(user_timesheet_positions, 1):
    log(f"\n=== Обработка позиции {idx}/{len(user_timesheet_positions)} ===")
    log(f"UT Position: {utp.name}")
    log(f"Проект: {utp.project}, Задача: {utp.document_name}, Пользователь: {utp.user}")

    time_details = frappe.db.get_all(
        'User Timesheet Position Details',
        filters={'parent': utp.name},
        fields=['date', 'hours'],
        order_by='date'
    )

    if not time_details:
        log(f"Пропускаем позицию {utp.name} - нет записей по дням")
        continue

    log(f"Найдено {len(time_details)} записей по дням для позиции {utp.name}")

    project = frappe.get_cached_doc('Project', utp.project)

    project_portfolio = get_project_portfolio(utp.project, None)

    # Получаем данные для кредитной проводки с учетом компании проекта
    party_data = get_data_for_party(worker, project.company)

    if not party_data:
        frappe.throw(f"Не найдена Статья учета для пользователя ({worker.wuser})")

    je_data = {
        'voucher_type': 'Journal Entry',
        'company': project.company,  # Устанавливаем компанию проекта
        'posting_date': user_timesheet.ts_valid_for,
        'user_remark': utp.name,
        'custom_user_timesheet': user_timesheet.name,
        'remark': user_timesheet.name
    }

    journal_entry = make_doc('Journal Entry', je_data)
    plan_task = find_task_with_plan(utp.project, utp.document_name, utp.project_role) or utp.document_name

    for detail in time_details:
        if not detail.hours or detail.hours <= 0:
            continue

        log_date = frappe.utils.getdate(detail.date)
        log(f"Обработка записи за {log_date}: {detail.hours} часов")

        pt_cost_level = get_pt_cost_level(utp.user, project.get('custom_ts_details'), log_date, worker)

        if not pt_cost_level:
            frappe.throw(f"Не найден cost level для {utp.user} на дату {log_date}")

        latest_rate = get_cost_rate(pt_cost_level, log_date)

        if not latest_rate:
            frappe.throw(f"Не найдена Ставка для cost level {pt_cost_level} на дату {log_date}")

        debit_account = get_account_for_task_hierarchy(utp.document_name, worker.wtype, log_date, project)

        if not debit_account:
            frappe.throw(f"Не найдена Статья для {utp.project} и связанных задач на дату {log_date}")

        credit_cost_center = get_worker_cost_center(worker, log_date)

        if not credit_cost_center and worker.wtype == "Employee":
            credit_cost_center = get_employee_cost_center(worker)

        if not credit_cost_center:
            log("Не удалось определить cost_center для кредитной проводки")

        debit_cost_center = credit_cost_center if project.custom_worker_cost_center else get_project_cost_center(project, log_date)

        if not debit_cost_center:
            log(f"Не найден Центр Затрат для {utp.project} на дату {log_date}")

        amount = detail.hours * latest_rate * K

        position_remark = f"{utp.name} | {detail.date}"

        business_areas = get_business_area(project, utp.document_name, log_date)

        credit_row = {
            'account': party_data.get("account"),
            'credit_in_account_currency': amount,
            'project': utp.project,
            'project_role': utp.project_role,
            'cost_center': credit_cost_center,
            'project_portfolio': project_portfolio,
            'task': plan_task,
            'user_remark': position_remark,
            'party_type': party_data.get("party_type"),
            'party': party_data.get("party")
        }
        log("Credit: " + frappe.utils.cstr(credit_row))
        journal_entry.append('accounts', credit_row)

        for area in business_areas:
            area_amount = amount * area.percent / 100

            debit_row = {
                'account': debit_account,
                'debit_in_account_currency': area_amount,
                'project': utp.project,
                'business_area': area.business_area,
                'cost_center': debit_cost_center,
                'project_portfolio': project_portfolio,
                'task': plan_task,
                'project_role': utp.project_role,
                'party_type': 'Worker',
                'party': worker.name,
                'user_remark': position_remark
            }
            log("Debit: " + frappe.utils.cstr(debit_row))
            journal_entry.append('accounts', debit_row)

    if not journal_entry.get('accounts'):
        log("Нет проводок для создания")
        continue

    journal_entry.insert(ignore_permissions=True)
    log("Journal Entry: " + frappe.utils.cstr(journal_entry))

    # Проверка баланса и добавление round_off при необходимости
    total_debit = sum(row.debit_in_account_currency or 0 for row in journal_entry.accounts)
    total_credit = sum(row.credit_in_account_currency or 0 for row in journal_entry.accounts)

    difference = total_credit - total_debit  # Положительная = нужно добавить в дебет, отрицательная = нужно убавить из дебета

    if abs(difference) > 0.009:  # Если разница больше 1 копейки
        round_off_account = get_round_off_account(project.company)

        log(f"Баланс не сходится. Дебет: {total_debit}, Кредит: {total_credit}, Разница: {difference}")

        # Просто добавляем разницу в дебет (может быть отрицательной)
        round_row = {
            'account': round_off_account,
            'debit_in_account_currency': round(difference, 2),  # Может быть отрицательным!
            'project': utp.project,
            'cost_center': debit_cost_center,
            'project_portfolio': project_portfolio,
            'task': plan_task,
            'project_role': utp.project_role,
            'user_remark': f"Корректировка баланса из-за округлений при расчетах: {utp.name}"
            #'party_type': 'Worker',
            #'party': worker.name
        }
        log("Round Off Row: " + frappe.utils.cstr(round_row))
        journal_entry.append('accounts', round_row)

        journal_entry.save(ignore_permissions=True)
        log(f"Добавлена корректировка баланса на сумму {round(difference, 2)}")

    journal_entry.submit()

    log(f"Создана проводка {journal_entry.name}")
